"""Warehouse fulfilment endpoints."""

from __future__ import annotations

from typing import Any

from orders.controllers.http import Response, not_found, conflict, bad_request, InvalidRequest, require_non_negative_int
from orders.domain.orders import Order
from orders.infrastructure.catalog import InMemoryProductCatalog
from orders.infrastructure.customers import InMemoryCustomerRepository
from orders.infrastructure.repository import InMemoryOrderRepository
from orders.infrastructure.stock import InMemoryStockRepository


class FulfilmentController:
    def __init__(self, orders: InMemoryOrderRepository, customers: InMemoryCustomerRepository,
                 catalog: InMemoryProductCatalog, stock: InMemoryStockRepository) -> None:
        self._orders = orders
        self._customers = customers
        self._catalog = catalog
        self._stock = stock

    def handle_packing_slip(self, order_id: str) -> Response:
        order = self._orders.get(order_id)
        if order is None:
            return not_found("order")
        if order.status == "cancelled":
            return conflict(ValueError(f"order {order_id} is cancelled"))
        customer = self._customers.get(order.customer_id)
        customer_name = customer.name if customer is not None else ""
        lines = [
            {
                "sku": item.sku,
                "name": self._catalog.get(item.sku).name if self._catalog.get(item.sku) is not None else "",
                "quantity": item.quantity,
            }
            for item in order.items
        ]
        return Response(200, {
            "order_id": order.order_id,
            "customer_name": customer_name,
            "lines": lines,
        })

    def handle_low_stock(self, threshold: Any) -> Response:
        try:
            threshold_int = require_non_negative_int(threshold, "threshold")
        except InvalidRequest as exc:
            return bad_request(exc)

        low_stock_products = []
        for product in self._catalog.list_all():
            if product.active and self._stock.get(product.sku) < threshold_int:
                low_stock_products.append({
                    "sku": product.sku,
                    "name": product.name,
                    "on_hand": self._stock.get(product.sku),
                })

        low_stock_products.sort(key=lambda p: (p["on_hand"], p["sku"]))
        return Response(200, {"products": low_stock_products})

